const season = data.season || 'Evergreen';
const objective = data.objective || 'Education and conversion';
const productFocus = data.product_focus || '';
const competitorFocus = data.competitor_focus || '';
const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
